sys_script_include.script:
var DayOneGateValidator = Class.create();
DayOneGateValidator.prototype = {
    initialize: function(planSysId) {
        this.planSysId = planSysId;
    },

    validateGate: function() {
        var reasons = [];
        var passed = true;

        var planGr = new GlideRecord('x_1919740_dayone_0_onboarding_plan');
        if (!planGr.get(this.planSysId)) {
            reasons.push('Plan not found');
            this._writeAudit('gate_blocked', reasons.join('; '));
            return { passed: false, reasons: reasons };
        }

        var threshold = parseInt(planGr.getValue('readiness_threshold'), 10) || 80;

        // (1) At least one applicable task
        var applicableGr = new GlideRecord('x_1919740_dayone_0_onboarding_task');
        applicableGr.addQuery('plan', this.planSysId);
        applicableGr.addQuery('task_state', '!=', 'cancelled');
        applicableGr.addQuery('task_state', '!=', 'not_applicable');
        applicableGr.query();

        if (applicableGr.getRowCount() === 0) {
            passed = false;
            reasons.push('No applicable tasks found');
        }

        // (2) At least one mandatory applicable task
        var mandatoryGr = new GlideRecord('x_1919740_dayone_0_onboarding_task');
        mandatoryGr.addQuery('plan', this.planSysId);
        mandatoryGr.addQuery('mandatory', true);
        mandatoryGr.addQuery('task_state', '!=', 'cancelled');
        mandatoryGr.addQuery('task_state', '!=', 'not_applicable');
        mandatoryGr.query();

        if (mandatoryGr.getRowCount() === 0) {
            passed = false;
            reasons.push('No mandatory applicable tasks found');
        }

        // (3) All mandatory applicable tasks are complete AND evidence_verified
        var incompleteMandatory = new GlideRecord('x_1919740_dayone_0_onboarding_task');
        incompleteMandatory.addQuery('plan', this.planSysId);
        incompleteMandatory.addQuery('mandatory', true);
        incompleteMandatory.addQuery('task_state', '!=', 'cancelled');
        incompleteMandatory.addQuery('task_state', '!=', 'not_applicable');
        var incompleteQuery = incompleteMandatory.addQuery('task_state', '!=', 'complete');
        incompleteQuery.addOrCondition('evidence_verified', '!=', '1');
        incompleteMandatory.query();

        if (incompleteMandatory.hasNext()) {
            passed = false;
            reasons.push('Not all mandatory tasks are complete and evidence verified');
        }

        // (4) Readiness score >= readiness_threshold
        var engine = new DayOneReadinessEngine(this.planSysId);
        var score = engine.calculateScore();

        if (score < threshold) {
            passed = false;
            reasons.push('Readiness score (' + score + ') is below threshold (' + threshold + ')');
        }

        // Write audit log entry
        if (passed) {
            this._writeAudit('gate_passed', 'All gate checks passed. Score: ' + score);
        } else {
            this._writeAudit('gate_blocked', reasons.join('; '));
        }

        return { passed: passed, reasons: reasons };
    },

    _writeAudit: function(eventType, details) {
        var auditGr = new GlideRecord('x_1919740_dayone_0_readiness_audit');
        auditGr.initialize();
        auditGr.setValue('plan', this.planSysId);
        auditGr.setValue('event_type', eventType == 'gate_passed' ? 'gate_passed' : (eventType == 'gate_blocked' ? 'gate_blocked' : 'gate_checked'));
        auditGr.setValue('performed_by', gs.getUserID());
        auditGr.setValue('details', details);
        auditGr.insert();
    },

    type: 'DayOneGateValidator'
};
